class PeakTest(unittest.TestCase):
    def test_matches_splot(self):
        """Exact, except the centre of mass, which numpy sums pairwise."""
        for name, x, y, (xpk, ymax, com, cen, fwhm) in SPLOT:
            s = stats(x, y)
            self.assertEqual((s.xpk, s.ymax, s.cen, s.fwhm), (xpk, ymax, cen, fwhm), name)
            if math.isnan(com):
                self.assertTrue(math.isnan(s.com), name)
            else:
                self.assertLessEqual(abs(s.com - com), 1e-12 * max(abs(com), 1.0), name)

    def test_empty_scan_has_no_statistics(self):
        self.assertIsNone(stats([], []))


if __name__ == "__main__":
    unittest.main()
